INSERT INTO "beregningsregel" VALUES(1,'{"skatteaar":2026,"skattesatsPromille":4,"reduksjonsfaktor":0.7,"bunnfradrag":0,"bunnfradragForFritid":false,"terminer":4,"utskrivningsgrense":300,"boligtyper":[{"id":"bolig","navn":"Bolig","tekst":"Enebolig, våningshus brukt som bolig, tomannsbolig, rekkehus og andre boligbygg","sats":10000,"kategori":"bolig","koder":[111,112,113,193,199,121,122,131,135,136,141,142,144]},{"id":"fritid","navn":"Fritid","tekst":"Hytte, helårsbolig eller våningshus brukt som fritidsbolig, seterhus, rorbu og utmarkskoie","sats":10000,"kategori":"fritid","koder":[161,162,163,171,172]}],"etasjer":[{"id":"hoved","navn":"Hovedetasje(r)","faktor":1,"hjelp":["Et plan der underkant dekke er mer enn 1,5 m over gjennomsnittlig planert terreng rundt bygningen. Fri bredde i høyden 1,9 m skal være minst 1,9 m.","Legg sammen bruksarealet for alle hovedetasjene. Arealet verdsettes med etasjefaktor 1,00."]},{"id":"under","navn":"Underetasje","faktor":0.6,"hjelp":["Et plan der underkant dekke eller himling er mer enn 0,75 m, men høyst 1,5 m over gjennomsnittlig planert terreng.","Oppgi hele underetasjens bruksareal, inkludert eventuell sokkelleilighet eller hybel. Restarealet får faktor 0,60; leilighets-/hybelarealet oppgis også i Herav-feltet og får faktor 0,80."]},{"id":"sokkel","navn":"Herav sokkelleilighet/hybel","faktor":0.8,"delAv":"under","hjelp":["Den delen av underetasjen som brukes som sokkelleilighet eller hybel. Dette er en del av arealet i Underetasje, ikke et ekstra areal.","Leilighets-/hybelarealet får faktor 0,80 og kan ikke være større enn hele underetasjen. Det telles bare én gang i beregningen."]},{"id":"loft","navn":"Loftsetasje","faktor":0.3,"hjelp":["Et rom over øverste alminnelige etasje som ikke oppfyller kravene til hovedetasje.","Fri høyde må være minst 1,9 m i en bredde på minst 0,6 m. Ved skråtak måles arealet inntil 0,6 m utenfor linjen med høyde 1,9 m. Oppgi måleverdig BRA; det får faktor 0,30."]},{"id":"kjeller","navn":"Kjelleretasje","faktor":0.2,"hjelp":["Et plan der underkant dekke eller himling er høyst 0,75 m over gjennomsnittlig planert terreng rundt bygningen.","Måleverdig kjellerareal får faktor 0,20. Er innvendig høyde under 1,90 m, skal arealet ikke tas med i eiendomsskatteberegningen."]}],"andreBygg":[{"id":"garasje","navn":"Garasje, uthus, naust","sats":2000},{"id":"anneks","navn":"Anneks med funksjon som bolig/fritidsbolig","sats":10000},{"id":"carport","navn":"Carport med tak, plasthall","sats":1000},{"id":"fjos","navn":"Landbruksbygning/fjøs","sats":1000,"landbruk":true}],"fritakMaksAreal":15,"tomt":{"pris":50,"maksAreal":2000,"arealUtenMaalebrev":2000,"maksArealGardsbruk":1000},"gardsbrukFaktor":0.9,"soner":[{"navn":"Leinesfjord, Saurselva, avkj. Småtindan, skogsvei Lagmansosen","faktor":1},{"navn":"Leines til Fløstrand (gnr. 11)","faktor":0.9},{"navn":"Laskestad, Steigberg, vei til Vik","faktor":0.9},{"navn":"Steigberg til Mjelle (Engeløya)","faktor":0.8},{"navn":"Nordfold, tverrvei Ytterkleiva – Ulvegraven, Mølnelva (Lakså), Kjærlighetskroken","faktor":0.9},{"navn":"Bogen, vei til Vik, t.o.m. Haug, t.o.m. Vinsnes, t.o.m. Dypvik","faktor":0.9},{"navn":"Skjenaust, Skånland, kryss til Markvatnet","faktor":0.8},{"navn":"Fure, Skjelvareid, Stensland, Dyping","faktor":0.8},{"navn":"Nordskott inkl. Båtberget, til Lund","faktor":0.8},{"navn":"Lakså","faktor":0.8},{"navn":"Øvrige områder i kommunen","faktor":0.7}],"ytre":[{"id":"normal","navn":"Normal beliggenhet","faktor":1,"tekst":"Gjelder de fleste eiendommer"},{"id":"darlig","navn":"Dårlig beliggenhet","faktor":0.8,"tekst":"Settes av kommunen ved besiktigelse"},{"id":"sarlig","navn":"Særlig dårlig beliggenhet","faktor":0.6,"tekst":"Settes av kommunen ved besiktigelse"}],"alder":[{"id":"2010","navn":"2010","tekst":"eller senere","hoy":null,"normal":1,"lav":null},{"id":"1986","navn":"1986–2009","hoy":1,"normal":0.9,"lav":[0.7,0.8]},{"id":"1960","navn":"1960–1985","hoy":0.9,"normal":0.8,"lav":[0.6,0.7]},{"id":"f60","navn":"Før 1960","hoy":0.75,"normal":0.6,"lav":[0.4,0.5]}],"standarder":[{"id":"normal","navn":"Normal standard","tekst":"Vanlig standard og vedlikehold for byggeåret"},{"id":"hoy","navn":"Vesentlig oppgradert, påbygd eller ombygd","tekst":"Klart høyere standard enn normalt for byggeåret"},{"id":"lav","navn":"Vesentlig dårligere enn normalt","tekst":"For eksempel svært dårlig isolasjon, råte eller setningsskader"}],"indreFaktorGjelderTomt":true}',0,'Leverte parametere. Skattesats og bunnfradrag for 2026 er ikke bekreftet mot kommunestyrets vedtak.');
